    members = ({"train": [1, 2], "validation": [3, 4], "test": [5, 6]}
               if layout == "train_validation_test" else {"train": [1, 2, 3, 4], "test": [5, 6]})
    loaded = json.loads(json.dumps(members))
    if mutation == "missing":
        del loaded["test"]
    elif mutation == "extra":
        loaded["other"] = [7]
    elif mutation == "duplicate":
        loaded["test"] = [5, 5, 6]
    elif mutation == "unknown":
        loaded["test"] = [5, 7]
    elif mutation == "coverage":
        loaded["test"] = [5]
    elif mutation == "empty":
        loaded["test"] = []
    elif mutation == "overlap":
        loaded["test"] = [2, 5, 6]
    with pytest.raises(ValueError):
        create_partitions(pd.DataFrame({"id": range(1, 7), "label": list("ABABAB")}), row_id="id", target="label", layout=cast(Any, layout), memberships=loaded)
